import { defineSecret } from "firebase-functions/params";

interface GoogleRecaptchaResponse {
  success: boolean;
  score?: number;
  action?: string;
  "error-codes"?: string[];
}

// Declare the secret via Firebase Secret Manager
export const recaptchaSecret = defineSecret("RECAPTCHA_SECRET_KEY");

/**
 * Validates a client-side reCAPTCHA v3 token against Google's verification servers.
 * Must be called with recaptchaSecret already declared in the function's secrets array.
 * @param {string} token The reCAPTCHA token generated by the Vue frontend.
 * @return {Promise<boolean>} True if the token is valid and scores as human (>= 0.5).
 */
export async function validateRecaptcha(token: string): Promise<boolean> {
  const secretKey = recaptchaSecret.value();

  if (!secretKey) {
    console.error(
      "Backend Configuration Error: RECAPTCHA_SECRET_KEY is not defined.",
    );
    return false;
  }

  try {
    const response = await fetch(
      "https://www.google.com/recaptcha/api/siteverify",
      {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          secret: secretKey,
          response: token,
        }),
      },
    );

    if (!response.ok) {
      console.error(
        `Google reCAPTCHA API returned an invalid status code: ${response.status}`,
      );
      return false;
    }

    const data = (await response.json()) as GoogleRecaptchaResponse;

    // reCAPTCHA v3 returns a score between 0.0 (bot) and 1.0 (human).
    // Enforce a baseline threshold of 0.5 for all protected endpoints.
    if (data.success && data.score !== undefined && data.score >= 0.5) {
      return true;
    }

    console.warn(
      `reCAPTCHA verification rejected. Success: ${data.success}, Score: ${data.score}`,
    );
    return false;
  } catch (error) {
    console.error(
      "Network communication failure during reCAPTCHA verification:",
      error,
    );
    return false;
  }
}
